def floating_whatsapp(path):
    product=PRODUCT_BY_SLUG.get(path.split('/')[-1]) if path.startswith('products/') else None
    if product:
        action='buying' if product[2]=='export' or product[0]=='berseem-seeds' else 'supplying'
        message=f'Hello Shiva Exim, I would like to discuss {action} {product[1].lower()}.'
    else:
        message='Hello Shiva Exim, I have a trade enquiry.'
    url=f'https://wa.me/{PHONE}?text={quote(message)}'
    return f'''<a class="whatsapp-float" href="{url}" target="_blank" rel="noopener" aria-label="Chat with Shiva Exim on WhatsApp (opens in a new tab)"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20.5 11.6a8.5 8.5 0 0 1-12.7 7.5L3 20.5l1.4-4.7a8.5 8.5 0 1 1 16.1-4.2Z"/><path d="m8 7.3 1.5-.2 1.1 2.6-1 1c.7 1.4 1.7 2.4 3.1 3.1l1-1 2.6 1.1-.2 1.5c-.1 1-1.2 1.5-2.2 1.2-4-1.1-6.4-3.5-7.5-7.5-.3-1 .2-2.1 1.2-2.2Z"/></svg><span>WhatsApp</span></a>'''

