    schema['founder']={'@type':'Person','name':'Savan Patel','sameAs':'https://www.linkedin.com/in/savan-patel-shivaexim/'}
    schema['description']='Seeds exporter and importer in Mehsana, Gujarat, India: cumin seed exporter, fennel seed exporter, alfalfa seed exporter and onion seed exporter, and importer of seeds and agricultural products for the Indian market.'
    schema['knowsAbout']=['Cumin seeds export','Fennel seeds export','Alfalfa seeds export','Onion seeds export','Seeds export','Seeds import']
    schema['areaServed']='Worldwide'
