    body=f'''<div class="wrap breadcrumb"><a href="/">Home</a><span>/</span><a href="/{trade}s/">{trade.title()}s</a><span>/</span><span>{name}</span></div><section class="product-detail wrap"><div><span class="eyebrow">{trade.upper()} PORTFOLIO · {group.upper()}</span><h1>{display_name}{' exporter from India' if trade=='export' else ' importer in India'}</h1>{also_known(slug)}<p class="lead">{desc}</p><div class="product-spec"><div><span>Product form</span><strong>{form}</strong></div><div><span>Trade direction</span><strong>{'Export enquiry from India' if trade=='export' else 'Import sourcing enquiry'}</strong></div><div><span>Grade & availability</span><strong>Confirmed on enquiry</strong></div><div><span>Packing & shipment terms</span><strong>Agreed with the quotation</strong></div></div></div><aside class="enquiry-panel"><span class="eyebrow">LET’S DISCUSS YOUR REQUIREMENT</span><h2>{'Buying' if trade=='export' else 'Supplying'} {lname}?</h2><p>Share your quantity, destination or origin, specification and preferred shipment timing.</p><a class="button" href="/contact/?product={slug}&intent={intent}">Enquire about {lname} ↗</a>{sample_btn}<a class="text-link" href="mailto:info@shivaexim.com?subject={name.replace(' ','%20')}%20enquiry">Email us directly →</a><small>No fixed prices or stock claims. Terms are confirmed individually.</small></aside></section><section class="requirement-details wrap"><div><span class="eyebrow">BEFORE WE QUOTE</span><h2>Details that help us respond.</h2></div><div><h3>For this product</h3><p>{spec.replace(';',' · ')}</p><h3>For the shipment</h3><p>Quantity · Packing preference · Destination port or country · Preferred shipment period · Required documents or test reports</p><p class="muted">Samples, certification, testing and destination compliance requirements should be discussed before confirming an order.</p></div></section><section class="featured wrap"><div class="section-heading"><h2>Explore related products.</h2><a class="text-link" href="/{trade}s/">Full {trade} portfolio →</a></div><div class="product-grid">{''.join(card(q) for q in [q for q in PRODUCTS if q[2]==trade and q[3]==group and q[0]!=slug][:3]) or ''.join(card(q) for q in [q for q in PRODUCTS if q[2]==trade and q[0]!=slug][:3])}</div></section>'''
    body=body.replace('<section class="requirement-details wrap">',render_media(slug,p)+render_product_details(p)+'<section class="requirement-details wrap">')
    body=body.replace('<section class="product-information wrap"', commercial_overview(p)+'<section class="product-information wrap"', 1)
